<?php require_once App\Core\Config::$DIR_BASE . '/App/Views/SBAdmin/Contract/ContractViewHelpers.php'; ?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><strong>Contrato <?= ctr_e($data['ContractId']); ?></strong><div><?= ctr_status($data['Contract']['Status'] ?? ''); ?></div></div><?php if (($data['Contract']['Status'] ?? '') === 'Draft'): ?><a class="btn btn-primary" href="/Contract/ContractItem/Show/<?= rawurlencode($data['ContractId']); ?>">Novo item</a><?php endif; ?></div>
<div class="table-responsive"><table class="table table-bordered table-sm"><thead><tr><th>Descrição</th><th>Serviço</th><th>Tipo</th><th>Qtd.</th><th>Preço</th><th>Desconto</th><th>Total</th><th>Franquia</th><th></th></tr></thead><tbody><?php foreach ($data['FormData'] as $row): ?><tr><td><?= ctr_e($row['Description']); ?></td><td><?= ctr_e($row['ServiceCode']); ?></td><td><?= ctr_e($row['ItemType']); ?></td><td><?= ctr_e($row['Quantity']); ?></td><td>R$ <?= ctr_money($row['UnitPrice']); ?></td><td>R$ <?= ctr_money($row['DiscountValue']); ?></td><td>R$ <?= ctr_money($row['LineTotal']); ?></td><td><?= ctr_e($row['UsageLimit']); ?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="/Contract/ContractItem/Show/<?= rawurlencode($data['ContractId']); ?>/<?= (int) $row['Id']; ?>">Abrir</a><?php if ($row['UsageLimit'] !== null): ?><a class="btn btn-sm btn-outline-secondary" href="/Contract/ContractLedger/Index/<?= (int) $row['Id']; ?>">Extrato</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
